const shiftsText = campData.shifts.map((s) => {
  const enrolledStr = s.enrolled ? ` (записалось ${s.enrolled} детей)` : "";
  return `- ${s.name}: ${s.dates} (${s.days} дней), ${s.price.toLocaleString("ru")} ₽${enrolledStr}${s.popular ? " — самая популярная" : ""}${!s.available ? " — МЕСТ НЕТ" : ""}`;
}).join("\n");
function getEnrolledByAge(age) {
  let ageKey;
  if (age <= 9) ageKey = "7-9";
  else if (age <= 12) ageKey = "10-12";
  else ageKey = "13-16";
  const counts = [];
  for (const s of campData.shifts) {
    if (s.available && s.enrolledByAge) {
      const n = s.enrolledByAge[ageKey];
      if (n) counts.push(`${s.name}: ${n} детей`);
    }
  }
  return counts.length ? counts.join(", ") : "";
}
const socialProofByAge = [8, 10, 12, 14].map((age) => {
  const s = getEnrolledByAge(age);
  return s ? `- возраст ${age} лет: ${s}` : "";
}).filter(Boolean).join("\n");
